function renderMarkList(){const root=document.querySelector('#markList'),count=document.querySelector('#markCount');if(!root)return;const data=marks(),entries=Object.entries(data);if(count)count.textContent=String(entries.length);root.innerHTML=entries.length?entries.map(([key,item])=>{const p=key.split('|'),book=currentBooks().find(b=>b.id===p[1]);return '<button class="saved-mark '+(item.color?'tone-'+item.color:'')+'" data-jump-mark="'+escapeHtml(key)+'"><b>'+escapeHtml(item.version||p[0])+' · '+escapeHtml(book?.name||p[1])+' '+escapeHtml(p[2])+':'+escapeHtml(p[3])+'</b>'+(item.note?'<span>'+escapeHtml(item.note)+'</span>':'<small>Marked verse</small>')+'</button>'}).join(''):'<p class="quiet">Your marked verses and notes will collect here.</p>';root.querySelectorAll('[data-jump-mark]').forEach(b=>b.onclick=()=>{const p=b.dataset.jumpMark.split('|'),v=p[0];if(bibleLibrary[v])activeVersion=v;if(versionSelect)versionSelect.value=activeVersion;syncBookOptions(p[1]);activeBook=findBook(p[1])||activeBook;syncChapterOptions(p[2]);showChapter(activeBook,p[2]);const line=selectedChapterVerses().find(x=>String(x.n)===p[3]);if(line)selectLine(line);document.querySelector('#reader')?.scrollIntoView({behavior:'smooth',block:'start'})})}
