function parseReference(ref){const m=String(ref||'').trim().match(/^(.+?)\s+(\d+)(?::(\d+)(?:\s*[-–]\s*(\d+))?)?$/);if(!m)return null;const book=findBook(m[1]);return book?{book,chapter:m[2],start:m[3]?Number(m[3]):null,end:m[4]?Number(m[4]):(m[3]?Number(m[3]):null)}:null}
function openReference(ref){const parsed=parseReference(ref);if(!parsed)return false;activeBook=parsed.book;syncBookOptions(parsed.book.id);syncChapterOptions(parsed.chapter);showChapter(parsed.book,parsed.chapter,parsed.start?{start:parsed.start,end:parsed.end||parsed.start}:null);if(parsed.start){const line=selectedChapterVerses().find(x=>Number(x.n)===parsed.start);if(line)selectLine(line)}return true}
