syncBookOptions();if(bookSelect){const initial=parseReference(new URLSearchParams(location.search).get('ref'));if(initial){activeBook=initial.book;syncBookOptions(initial.book.id);syncChapterOptions(initial.chapter);showChapter(initial.book,initial.chapter,initial.start?{start:initial.start,end:initial.end||initial.start}:null);if(initial.start){const line=selectedChapterVerses().find(x=>Number(x.n)===initial.start);if(line)selectLine(line)}}else showChapter(activeBook,activeChapter)}
bookSelect?.addEventListener('change',()=>{activeBook=currentBooks().find(b=>b.id===bookSelect.value);syncChapterOptions();showChapter(activeBook,activeChapter)});chapterSelect?.addEventListener('change',()=>{activeChapter=chapterSelect.value;showChapter(activeBook,activeChapter)});document.querySelector('#goToChapter')?.addEventListener('click',()=>showChapter(activeBook,chapterSelect.value));
