function moveChapter(delta){const books=currentBooks(),bi=books.findIndex(b=>b.id===activeBook.id),chapters=Object.keys(activeBook.chapters).sort((a,b)=>Number(a)-Number(b)),ci=chapters.indexOf(String(activeChapter));let nb=activeBook,nc;if(ci+delta>=0&&ci+delta<chapters.length)nc=chapters[ci+delta];else{const next=books[bi+delta>0?bi+1:bi-1];if(!next)return;nb=next;const list=Object.keys(nb.chapters).sort((a,b)=>Number(a)-Number(b));nc=delta>0?list[0]:list[list.length-1]}syncBookOptions(nb.id);syncChapterOptions(nc);showChapter(nb,nc)}
