const searchInput=document.querySelector('#bibleSearch'),searchButton=document.querySelector('#bibleSearchButton'),results=document.querySelector('#bibleResults');
function searchBible(){if(!searchInput||!results)return;const q=searchInput.value.trim().toLowerCase();if(!q){results.innerHTML='<p class="quiet">Enter a verse reference or word to search the full included Bible texts.</p>';return}const ref=parseReference(searchInput.value);if(ref&&ref.start){openReference(searchInput.value);document.querySelector('#reader')?.scrollIntoView({behavior:'smooth',block:'start'});results.innerHTML='<p class="quiet">Opened '+escapeHtml(searchInput.value)+'. Use the verse marker to annotate it.</p>';return}const matches=[];for(const book of currentBooks()){let stop=false;for(const[chapter,lines]of Object.entries(book.chapters)){for(const line of lines){if((book.name+' '+chapter+':'+line.n+' '+line.t).toLowerCase().includes(q)){matches.push({book,chapter,line});if(matches.length>=50){stop=true;break}}}if(stop)break}if(stop)break}results.innerHTML=matches.length?matches.map((x,i)=>'<button class="result-row" data-result="'+i+'"><span>'+escapeHtml(x.book.name)+' '+x.chapter+':'+escapeHtml(x.line.n)+' · '+activeVersion+'</span><small>'+escapeHtml(x.line.t.slice(0,155))+'…</small></button>').join(''):'<p class="quiet">No matches found in '+(activeVersion==='WEB'?'the World English Bible':'the King James Version')+'.</p>';results.querySelectorAll('[data-result]').forEach(button=>button.onclick=()=>{const x=matches[+button.dataset.result];syncBookOptions(x.book.id);syncChapterOptions(x.chapter);showChapter(x.book,x.chapter);const line=selectedChapterVerses().find(v=>String(v.n)===String(x.line.n));if(line)selectLine(line);document.querySelector('#reader')?.scrollIntoView({behavior:'smooth',block:'start'})})}
